using Astronomy.MediaFactory.Core.KnowledgeFoundation; using Astronomy.MediaFactory.Core.KnowledgeFoundation.Query; using Xunit;
namespace Astronomy.MediaFactory.Tests.KnowledgeFoundation.Query;
public sealed class AstronomyKnowledgeSubjectFilterTests{[Fact]public void Constructs_and_normalizes(){var caller=new List<AstronomyEntityReference>{new("z"),new("a"),new("a")};var f=new AstronomyKnowledgeSubjectFilter(caller);caller.Add(new("b"));Assert.Equal(new[]{"a","z"},f.Values.Select(x=>x.EntityId));Assert.Throws<NotSupportedException>(()=>((IList<AstronomyEntityReference>)f.Values).Add(new("c")));}[Fact]public void Supports_all_mode(){var f=new AstronomyKnowledgeSubjectFilter([new("a")],AstronomyKnowledgeQueryMatchMode.All);Assert.Equal(AstronomyKnowledgeQueryMatchMode.All,f.MatchMode);}[Fact]public void Rejects_invalid_inputs(){Assert.Throws<ArgumentException>(()=>new AstronomyKnowledgeSubjectFilter([]));Assert.Throws<ArgumentException>(()=>new AstronomyKnowledgeSubjectFilter([null!]));Assert.Throws<ArgumentOutOfRangeException>(()=>new AstronomyKnowledgeSubjectFilter([new("a")],(AstronomyKnowledgeQueryMatchMode)99));}}
